// AUTOMAP_Init - Initializes the automap subsystem.
// Loads DC6 sprite assets for all 4 act map tilesets
// (MaxiMap, Act2Map, Act4Map, ExTnMap in normal/small variants).
// Builds the cell-to-frame mapping table from automap.txt data.
// Reads registry settings: AutoMapFade, Centers, Party, PartyNames, Left.
// Called once from InitializeUI.
// Source: .\\UI\\automap.cpp
void __stdcall AUTOMAP_Init() {
    // Static local variables (originally global data)
    static uint32_t gnAutoMapInitialZoomLevel[98] = {
    0x0,
    0x0,
    0x1,
    0x0,
    0x2,
    0x0,
    0x3,
    0x0,
    0x6,
    0x1,
    0x7,
    0x1,
    0x8,
    0x1,
    0xb,
    0x2,
    0xc,
    0x2,
    0xd,
    0x3,
    0xe,
    0x3,
    0x14,
    0x4,
    0x26,
    0x4,
    0x15,
    0x5,
    0x27,
    0x5,
    0x2e,
    0x6,
    0x2f,
    0x6,
    0x30,
    0x6,
    0x31,
    0x6,
    0x33,
    0x7,
    0x34,
    0x7,
    0x35,
    0x7,
    0x36,
    0x7,
    0x3c,
    0x8,
    0x46,
    0x8,
    0x3d,
    0x9,
    0x47,
    0x9,
    0x78,
    0xa,
    0xa9,
    0xa,
    0xab,
    0xa,
    0x79,
    0xb,
    0xaa,
    0xb,
    0xac,
    0xb,
    0x101,
    0xc,
    0x102,
    0xc,
    0x103,
    0xc,
    0x10a,
    0xd,
    0x10b,
    0xd,
    0x151,
    0xe,
    0x152,
    0xe,
    0x1d8,
    0xf,
    0x1d9,
    0xf,
    0x1da,
    0xf,
    0x1db,
    0xf,
    0x208,
    0x10,
    0x209,
    0x10,
    0x20a,
    0x10,
    0x215,
    0x11,
    0x216,
    0x11
}; D2_STATIC_GUARD(gnAutoMapInitialZoomLevel, "D2Client::UI::Automap::AUTOMAP_Init::gnAutoMapInitialZoomLevel");

    int nCellId;
    uint32_t* pPriorityValue;
    int32_t nRegValue = 0;
    AUTOMAP_LoadDC6Sprites();
    uint32_t* pPriorityTable = gnAutoMapCellPriority;
    for (nCellId = 0x800; nCellId; nCellId--) {
      *pPriorityTable = -1;
      pPriorityTable++;
    }

    uint32_t* pCellEntry = gnAutoMapInitialZoomLevel;
    do {
      uint32_t nCellIndex;
      nCellIndex = *pCellEntry;
      pPriorityValue = pCellEntry + 1;
      pCellEntry += 2;
      gnAutoMapCellPriority[nCellIndex] = *pPriorityValue;
    } while (pCellEntry < gnAutoMapInitialZoomLevel + 98);
    // The original's bound is `pCellEntry < 0x7113e0`, and 0x7113e0 is where nAutoMapCenters
    // happens to sit immediately after this 49-pair table - so the compiler spelled "the end of
    // the table" as the NEXT GLOBAL'S ADDRESS. After relinking the two are nowhere near each
    // other, the loop ran away, and gnAutoMapCellPriority[garbage] faulted in AUTOMAP_Init the
    // moment a character entered the game.
    // Retire-When: the address-literal pass rewrites a loop bound that is another symbol's
    // address into that symbol's own extent.

    nRegValue = 0;
    Storm::Source::SReg::SRegLoadValue("Diablo II", "AutoMapFade", 0, &nRegValue);
    nAutoMapFade = nRegValue;
    nRegValue = 1;
    Storm::Source::SReg::SRegLoadValue("Diablo II", "AutoMap Centers", 0, &nRegValue);
    nAutoMapCenters = nRegValue;
    nRegValue = 1;
    Storm::Source::SReg::SRegLoadValue("Diablo II", "AutoMap Party", 0, &nRegValue);
    nAutoMapParty = nRegValue;
    nRegValue = 1;
    Storm::Source::SReg::SRegLoadValue("Diablo II", "AutoMap Party Names", 0, &nRegValue);
    AutoMapPartyNames = nRegValue;
    nRegValue = 1;
    Storm::Source::SReg::SRegLoadValue("Diablo II", "AutoMap Left", 0, &nRegValue);
    AutoMapLeft = nRegValue;
    AutoMapLeft2 = nRegValue;
    AutoMapLeft3 = nRegValue;
}

// AUTOMAP_Free - Frees all automap resources.
// Saves current layer to disk, frees all cell allocations,
// frees DC6 sprite assets, frees all automap layers.
// Called from FreeDraw during game cleanup.
// Source: .\\UI\\automap.cpp
// @sourcefile .\UI\automap.cpp
void __stdcall AUTOMAP_Free() {
    D2AutomapLayerStrc* pMemoryToFree;
    AUTOMAP_SaveCurrentLayer();
    AUTOMAP_FreeCurrentLayerCells();
    DC6** ppDC6 = pAutoMapDC6;
    do {
      if (*ppDC6) {
        Core::Archive::DC6_FreeAndDelete(*ppDC6);
      }

      *ppDC6 = 0;
      ppDC6++;
      pMemoryToFree = sgpAutomapLayer;
    } while ((int)ppDC6 < (intptr_t)((char*)&pAutoMapDC6 + sizeof(pAutoMapDC6)));

    while (pMemoryToFree) {
      D2AutomapLayerStrc* pNextLayer;
      pNextLayer = pMemoryToFree->pNext;
      D2_FREE_AT(pMemoryToFree, ".\\UI\\automap.cpp", 0xc06);
      pMemoryToFree = pNextLayer;
    }

    sgpAutomapLayerEx = 0;
    sgpAutomapLayer = 0;
}

